package com.careflow.hospital.appointments;
import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="appointment") public class Appointment {@Id @Column(name="appointment_id")private UUID id;@Column(name="appointment_number",nullable=false)private String appointmentNumber;@Column(name="patient_id",nullable=false)private UUID patientId;@Column(name="doctor_id",nullable=false)private UUID doctorId;@Column(name="reservation_id",unique=true)private UUID reservationId;@Column(name="starts_at",nullable=false)private Instant startsAt;@Column(name="ends_at",nullable=false)private Instant endsAt;@Column(nullable=false)private String status;@Column(name="cancellation_reason")private String cancellationReason;@Column(name="rescheduled_from_appointment_id")private UUID rescheduledFromAppointmentId;@Column(name="rescheduled_to_appointment_id")private UUID rescheduledToAppointmentId;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected Appointment(){}public Appointment(UUID patientId,UUID doctorId,UUID reservationId,Instant startsAt,Instant endsAt){this(patientId,doctorId,reservationId,startsAt,endsAt,null);}public Appointment(UUID patientId,UUID doctorId,UUID reservationId,Instant startsAt,Instant endsAt,UUID rescheduledFromAppointmentId){id=UUID.randomUUID();appointmentNumber="APT-"+id.toString().replace("-","").substring(0,12).toUpperCase(Locale.ROOT);this.patientId=patientId;this.doctorId=doctorId;this.reservationId=reservationId;this.startsAt=startsAt;this.endsAt=endsAt;this.rescheduledFromAppointmentId=rescheduledFromAppointmentId;status="CONFIRMED";createdAt=Instant.now();updatedAt=createdAt;}public void cancel(String reason){if(!Set.of("REQUESTED","CONFIRMED").contains(status))throw new IllegalStateException("Only requested or confirmed appointments can be cancelled.");status="CANCELLED";cancellationReason=reason;updatedAt=Instant.now();}public void markRescheduled(UUID replacementId){if(!"CONFIRMED".equals(status))throw new IllegalStateException("Only confirmed appointments can be rescheduled.");status="RESCHEDULED";rescheduledToAppointmentId=replacementId;updatedAt=Instant.now();}public void transition(String next){Map<String,Set<String>> allowed=Map.of("CONFIRMED",Set.of("CHECKED_IN","NO_SHOW","IN_PROGRESS","COMPLETED"),"CHECKED_IN",Set.of("IN_PROGRESS","COMPLETED"),"IN_PROGRESS",Set.of("COMPLETED"));if(!allowed.getOrDefault(status,Set.of()).contains(next))throw new IllegalStateException("Invalid appointment state transition from "+status+" to "+next+".");status=next;updatedAt=Instant.now();}public UUID getId(){return id;}public String getAppointmentNumber(){return appointmentNumber;}public UUID getPatientId(){return patientId;}public UUID getDoctorId(){return doctorId;}public UUID getReservationId(){return reservationId;}public Instant getStartsAt(){return startsAt;}public Instant getEndsAt(){return endsAt;}public String getStatus(){return status;}public String getCancellationReason(){return cancellationReason;}public UUID getRescheduledFromAppointmentId(){return rescheduledFromAppointmentId;}public UUID getRescheduledToAppointmentId(){return rescheduledToAppointmentId;}public Instant getCreatedAt(){return createdAt;}}
